truncate risk_flags, risk_assessments;

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R01','Occupancy & leased-rate integrity','Occupancy & Vacancy',10,null,'Physical occupancy counts bodies in units; leased rate counts signed leases net of notices. A large leased-below-occupied gap signals a forward vacancy wave that the seller''s underwritten vacancy does not capture.','Pull the notice-to-vacate report and 60-day leasing velocity; re-underwrite vacancy to the leased rate until velocity proves otherwise.',true,false,'{"l1Gap":0.05,"l2Gap":0.1,"stabilizedOcc":0.95}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R02','Loss-to-lease disclosure','Revenue / Rent',2,null,'Loss-to-lease is the gap between in-place and market rent — the core of any rent upside thesis. Without a unit-level roll and market rents it cannot be verified.','Obtain the full unit-level rent roll with market-rent column; compute LTL by unit and by floor plan.',true,false,'{}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R03','Year-1 rent-growth aggressiveness','Revenue / Rent',6,null,'Front-loaded rent growth inflates Year-1 NOI and therefore going-in value. It is only credible with signed-lease trade-out evidence, especially when trailing rents are flat-to-down.','Require signed new-lease and renewal trade-out data for the last 6 months before crediting Year-1 growth.',true,false,'{"maxGrowth":0.03}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R04','Renovation / rent-premium substantiation','Value-Add',2,null,'Marketed upgrade premiums ($/unit/month) mean nothing without $/SF normalization and achieved-lease evidence — unit-size mix can masquerade as renovation lift (the classic OM overstatement).','Obtain the ''ROIs & Amenities'' data-room sheet; normalize premiums to $/SF against classic units of like size.',true,false,'{}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R05','NOI quality / manufactured NOI','NOI Quality',12,null,'NOI lifted by cutting expenses below trailing actuals — rather than growing revenue — is not durable. It is the single most common OM overstatement and directly inflates value at the going-in cap.','Re-underwrite controllable expenses to T-12 actuals; treat ''market adjustments'' as unproven until third-party bids support them.',true,false,'{"ctrlCut":0.05,"lineCut":0.25}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R06','Expense anomaly — insurance step-change','Expenses',5,null,'A >50% swing between trailing and underwritten insurance means either T-12 is understated (further NOI drag) or the UW is padded — either way the true run-rate is unknown without the bound policy.','Obtain the bound policy and 5-year loss runs; set insurance to the quoted renewal, not a $/unit rule of thumb.',true,false,'{"maxDelta":0.5}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R07','Management-fee adequacy','Expenses',4,null,'A below-market management fee understates operating cost and overstates NOI. Mixed-use high-rises with ground-floor retail warrant 2.5–3.5%.','Underwrite management to 3.0% of EGI (market for a 12-story mixed-use asset).',false,false,'{"minPct":0.025,"marketPct":0.03}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R08','Capital-expenditure & reserve adequacy','Capital / Value-Add',10,null,'Thin reserves plus a value-add thesis with zero renovation capital means the upside is claimed but unfunded — the buyer pays for NOI growth that requires unbudgeted capital to achieve.','Budget interior + fitness-center capital and raise reserves to ≥$250/unit for a 12-story asset; net the capital from the bid.',true,false,'{"minReservePU":250}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R09','Deferred maintenance & building systems','Physical / Capital',5,null,'A single-membrane roof and other major systems near end of service life are large, lumpy costs. Absent a PCA, they are unquantified and unreserved.','Commission a Property Condition Assessment; obtain roof age/warranty and a 12-year capital plan.',true,false,'{"roofLifeYears":20}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R10','Cap-rate & pricing sufficiency','Pricing / Valuation',6,null,'An OM offered unpriced gives no going-in cap or price-per-unit anchor. Value must be triangulated from re-underwritten NOI and a cap-rate matrix, not the seller''s numbers.','Confirm pricing guidance; value off re-underwritten NOI via a cap-rate sensitivity matrix; do not bid to the seller''s Year-1 NOI.',true,true,'{}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R11','DSCR / debt-service coverage','Debt / Leverage',5,null,'Coverage below 1.25x on a fully-amortizing basis means the asset barely services its debt once interest-only burns off — a refinancing and distribution risk.','Size debt to a 1.25x amortizing DSCR floor; stress the post-IO coverage before committing.',false,false,'{"minDSCR":1.25}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R12','Leverage / LTV','Debt / Leverage',2,null,'Leverage above 75% leaves a thin equity cushion against value declines.','Keep leverage ≤65–70% given the aggressive OM basis.',false,false,'{"maxLTV":0.75}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R13','Debt yield','Debt / Leverage',2,null,'Debt yield (NOI ÷ loan) is the lender''s downside test; below ~8% signals aggressive proceeds relative to income.','Confirm lender debt-yield floor; size proceeds to ≥8% on re-underwritten NOI.',false,false,'{"minDebtYield":0.08}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R14','Submarket supply / demand fundamentals','Market',8,null,'Supply-constrained, high-income submarkets protect occupancy and pricing power — the demand side of the thesis. A PASS here proves the rule set discriminates rather than flagging everything.','Confirm the multifamily (not office/retail) vacancy and 2024–2028 delivery pipeline with CoStar.',false,false,'{"maxVacancy":0.05}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R15','Comparable-set integrity','Comparables',2,null,'Rent comps drive the mark-to-market thesis; internal inconsistencies between OM sections undermine any premium/discount conclusion.','Rebuild the comp set from primary source (CoStar) at like vintage/geography; reconcile the OM''s conflicting figures.',true,false,'{}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R16','Regulatory exposure','Regulatory',1,null,'Rent regulation and undisclosed affordable/restricted units cap upside and change the risk profile.','Confirm no affordable/income-restricted units and no local rent-stabilization overlay in the applicable jurisdiction.',true,false,'{}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R17','Property-tax & reassessment risk','Tax',4,null,'A sale can trigger reassessment and assessment rates change; underwriting taxes flat to the current bill understates go-forward expense.','Model a reassessment-on-sale scenario at the purchase basis; confirm the current mill levy and assessment ratio.',true,false,'{"maxTaxPctEgi":0.15}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R18','Lease rollover & retail anchor risk','Lease Rollover',2,null,'Concentrated retail rollover and an anchor rent abatement create near-term income volatility that the blended pro forma masks.','Abstract every retail lease; model any disclosed abatement and the retail rollover schedule explicitly.',true,false,'{"maxRollPct":0.2}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

insert into risk_rules (rule_id,name,category,weight,page,why_it_matters,next_action,dd_required,guardrail,params,version,active)
values ('R19','Document integrity','Data Integrity',4,null,'Internal contradictions in the OM undermine confidence in every extracted figure and must be reconciled before any number is trusted.','Reconcile each inconsistency against the rent roll and T-12 source documents before relying on OM figures.',true,true,'{"maxInconsistencies":0}'::jsonb,'1.0',true)
on conflict (rule_id) do update set name=excluded.name,category=excluded.category,weight=excluded.weight,page=excluded.page,why_it_matters=excluded.why_it_matters,next_action=excluded.next_action,dd_required=excluded.dd_required,guardrail=excluded.guardrail,params=excluded.params,version=excluded.version,updated_at=now();

