values ('R20','Missing due-diligence coverage','Due Diligence',8,null,'Core underwriting inputs absent from the OM mean the screening rests on marketing figures; the deal cannot clear IC until they are obtained.','Issue the DD request list; do not advance to IC until the rent roll, T-12 statement, leases, and PCA are received.',true,true,'{"maxMissing":3}'::jsonb,'1.0',true)
