  returning id
)
insert into risk_flags (assessment_id,rule_id,rule_name,category,status,severity,level,weight,points_lost,evidence,om_page,why_it_matters,financial_impact,recommended_next_action,additional_dd_required,guardrail)
select a.id, f.* from a cross join (values
('R05','NOI quality / manufactured NOI','NOI Quality','FLAG','CRITICAL',2,12,12,'Seller Year-1 NOI ($6,911,304) exceeds T-12 actual ($6,859,742) via expense cuts, not revenue: Turnover -32.1% and R&M -25.7% below T-12.',null,'NOI lifted by cutting expenses below trailing actuals — rather than growing revenue — is not durable. It is the single most common OM overstatement and directly inflates value at the going-in cap.','~$67,527/yr of NOI overstated → ≈$1,286,229 of value at 5.3%.','Re-underwrite controllable expenses to T-12 actuals; treat ''market adjustments'' as unproven until third-party bids support them.',true,false),
('R01','Occupancy & leased-rate integrity','Occupancy & Vacancy','FLAG','CRITICAL',2,10,10,'96.0% occupied but only 85.0% leased — a 11-pt gap (~24 units under notice) vs an underwritten 5.0% vacancy.',null,'Physical occupancy counts bodies in units; leased rate counts signed leases net of notices. A large leased-below-occupied gap signals a forward vacancy wave that the seller''s underwritten vacancy does not capture.','~$782,059/yr NOI exposure if leased rate holds (≈$14,896,370 of value at 5.3%).','Pull the notice-to-vacate report and 60-day leasing velocity; re-underwrite vacancy to the leased rate until velocity proves otherwise.',true,false),
('R08','Capital-expenditure & reserve adequacy','Capital / Value-Add','FLAG','CRITICAL',2,10,10,'Reserves only $137/unit for a 2015 12-story asset; the marketed value-add thesis carries $0 of renovation capital.',null,'Thin reserves plus a value-add thesis with zero renovation capital means the upside is claimed but unfunded — the buyer pays for NOI growth that requires unbudgeted capital to achieve.','Reserve shortfall ~$24,634/yr (≈$469,219 of value); interior renovation est. $1.5–2.5M unfunded.','Budget interior + fitness-center capital and raise reserves to ≥$250/unit for a 12-story asset; net the capital from the bid.',true,false),
('R20','Missing due-diligence coverage','Due Diligence','FLAG','HIGH',1,8,6,'8 critical DD items not provided in the OM: Full unit-level rent roll, T-12 operating statement + GL, Leased-vs-occupied / NTV report, Bound insurance policy + loss runs, …',null,'Core underwriting inputs absent from the OM mean the screening rests on marketing figures; the deal cannot clear IC until they are obtained.','Screening rests on marketing figures until DD is received.','Issue the DD request list; do not advance to IC until the rent roll, T-12 statement, leases, and PCA are received.',true,true),
('R03','Year-1 rent-growth aggressiveness','Revenue / Rent','FLAG','HIGH',2,6,4.5,'Seller underwrites +3.5% Year-1 rent growth off the T-3, yet T-12 GSR ($7,601,310) exceeds T-3 annualized ($7,556,129) — rents are decelerating, not accelerating.',null,'Front-loaded rent growth inflates Year-1 NOI and therefore going-in value. It is only credible with signed-lease trade-out evidence, especially when trailing rents are flat-to-down.','~$264,465 of Year-1 revenue not yet in place.','Require signed new-lease and renewal trade-out data for the last 6 months before crediting Year-1 growth.',true,false),
('R06','Expense anomaly — insurance step-change','Expenses','FLAG','MEDIUM',1,5,2,'Insurance underwritten at $139,431 vs T-12 $57,596 — a 142.1% step-change.',null,'A >50% swing between trailing and underwritten insurance means either T-12 is understated (further NOI drag) or the UW is padded — either way the true run-rate is unknown without the bound policy.','$81,835 of unexplained annual expense swing.','Obtain the bound policy and 5-year loss runs; set insurance to the quoted renewal, not a $/unit rule of thumb.',true,false),
('R09','Deferred maintenance & building systems','Physical / Capital','FLAG','MEDIUM',1,5,2,'No PCA in the OM. Roof is original TPO from 2015 (~11 yrs, mid-life). Boiler replaced 2024 (mitigant).',null,'A single-membrane roof and other major systems near end of service life are large, lumpy costs. Absent a PCA, they are unquantified and unreserved.','Roof replacement est. $1.5–2.5M within a typical hold — unreserved.','Commission a Property Condition Assessment; obtain roof age/warranty and a 12-year capital plan.',true,false),
('R11','DSCR / debt-service coverage','Debt / Leverage','FLAG','MEDIUM',1,5,2,'At 60.0% LTV / 6.3% / 30-yr, coverage is 1.41x during the 2-yr IO but only 1.19x once amortizing — below the 1.25x floor.',null,'Coverage below 1.25x on a fully-amortizing basis means the asset barely services its debt once interest-only burns off — a refinancing and distribution risk.','Post-IO coverage cushion is thin; distributions compress when the loan begins amortizing.','Size debt to a 1.25x amortizing DSCR floor; stress the post-IO coverage before committing.',false,false),
('R07','Management-fee adequacy','Expenses','FLAG','MEDIUM',1,4,1.6,'Seller underwrites a 2.0% management fee vs a 3.0% market benchmark; T-12 shows $0 (self-managed) — no third-party benchmark.',null,'A below-market management fee understates operating cost and overstates NOI. Mixed-use high-rises with ground-floor retail warrant 2.5–3.5%.','~$96,590/yr understated → ≈$1,839,810 of value at 5.3%.','Underwrite management to 3.0% of EGI (market for a 12-story mixed-use asset).',false,false),
('R17','Property-tax & reassessment risk','Tax','FLAG','MEDIUM',1,4,1.6,'RE taxes $786,927 = 8.1% of EGI, grown only ~3%/yr off the assessor FMV; a sale near $124,638,000 FMV plus assessment-rate changes in Metro City create reassessment exposure not modeled.',null,'A sale can trigger reassessment and assessment rates change; underwriting taxes flat to the current bill understates go-forward expense.','Each +10% to the tax bill ≈ $78,693/yr of NOI.','Model a reassessment-on-sale scenario at the purchase basis; confirm the current mill levy and assessment ratio.',true,false),
('R19','Document integrity','Data Integrity','FLAG','MEDIUM',2,4,1.6,'5 documented inconsistencies: Framing described inconsistently between the summary and the construction detail; Physical occupancy stated well above leased rate; Comparable property unit count conflicts between two pages; ….',null,'Internal contradictions in the OM undermine confidence in every extracted figure and must be reconciled before any number is trusted.','Extraction confidence reduced; verify all figures against source docs.','Reconcile each inconsistency against the rent roll and T-12 source documents before relying on OM figures.',true,true),
('R04','Renovation / rent-premium substantiation','Value-Add','FLAG','MEDIUM',1,2,0.8,'OM markets interior-upgrade premiums on a $/unit basis with no $/SF normalization and no achieved-lease evidence; the supporting ROI detail is referenced but not included.',null,'Marketed upgrade premiums ($/unit/month) mean nothing without $/SF normalization and achieved-lease evidence — unit-size mix can masquerade as renovation lift (the classic OM overstatement).','Upgrade upside unverified — exclude from value until substantiated.','Obtain the ''ROIs & Amenities'' data-room sheet; normalize premiums to $/SF against classic units of like size.',true,false),
('R15','Comparable-set integrity','Comparables','FLAG','MEDIUM',1,2,0.8,'Comp rent/PSF figures conflict between sections of the OM. Subject $2.94/SF vs the Central submarket average $3.28/SF.',null,'Rent comps drive the mark-to-market thesis; internal inconsistencies between OM sections undermine any premium/discount conclusion.','Mark-to-market upside cannot be sized until comps are reconciled.','Rebuild the comp set from primary source (CoStar) at like vintage/geography; reconcile the OM''s conflicting figures.',true,false),
('R18','Lease rollover & retail anchor risk','Lease Rollover','FLAG','MEDIUM',1,2,0.8,'Retail income volatility: anchor Anchor restaurant tenant (47.7% of retail SF) has a 2026 base-rent abatement; ~20.0% of retail SF rolls within the hold.',null,'Concentrated retail rollover and an anchor rent abatement create near-term income volatility that the blended pro forma masks.','Near-term retail income at risk of re-lease downtime and TI/LC.','Abstract every retail lease; model any disclosed abatement and the retail rollover schedule explicitly.',true,false),
('R16','Regulatory exposure','Regulatory','FLAG','LOW',1,1,0.2,'Metro City: no statewide rent control (favorable), but the OM does not affirmatively disclose the absence of affordable/income-restricted units.',null,'Rent regulation and undisclosed affordable/restricted units cap upside and change the risk profile.','Low — confirmatory only.','Confirm no affordable/income-restricted units and no local rent-stabilization overlay in the applicable jurisdiction.',true,false),
('R02','Loss-to-lease disclosure','Revenue / Rent','INSUFFICIENT_DATA','INSUFFICIENT_DATA',null,2,1,'No unit-level rent roll, no market-rent column and no stated loss-to-lease. Subject in-place $2,808 ($2.94/SF) vs a Central submarket average of $3.28/SF.',null,'Loss-to-lease is the gap between in-place and market rent — the core of any rent upside thesis. Without a unit-level roll and market rents it cannot be verified.','Rent-upside thesis unquantifiable from the OM.','Obtain the full unit-level rent roll with market-rent column; compute LTL by unit and by floor plan.',true,false),
('R10','Cap-rate & pricing sufficiency','Pricing / Valuation','INSUFFICIENT_DATA','INSUFFICIENT_DATA',null,6,3,'OM is unpriced and free-and-clear — no asking price or going-in cap. At the assessor FMV ($124,638,000): 5.3% on re-underwritten NOI vs 5.5% on the seller''s Year-1 NOI.',null,'An OM offered unpriced gives no going-in cap or price-per-unit anchor. Value must be triangulated from re-underwritten NOI and a cap-rate matrix, not the seller''s numbers.','Each 25 bps of cap ≈ $6,296,573 of value swing at this NOI.','Confirm pricing guidance; value off re-underwritten NOI via a cap-rate sensitivity matrix; do not bid to the seller''s Year-1 NOI.',true,true),
('R12','Leverage / LTV','Debt / Leverage','PASS','PASS',null,2,0,'Assumed LTV 60.0% is conservative (≤75.0%).',null,'Leverage above 75% leaves a thin equity cushion against value declines.','None — mitigant present.','Keep leverage ≤65–70% given the aggressive OM basis.',false,false),
('R13','Debt yield','Debt / Leverage','PASS','PASS',null,2,0,'Debt yield 8.8% on re-underwritten NOI — above the 8.0% floor.',null,'Debt yield (NOI ÷ loan) is the lender''s downside test; below ~8% signals aggressive proceeds relative to income.','None — mitigant present.','Confirm lender debt-yield floor; size proceeds to ≥8% on re-underwritten NOI.',false,false),
('R14','Submarket supply / demand fundamentals','Market','PASS','PASS',null,8,0,'Central submarket shows constrained supply: office vacancy 4.0%, retail 2.0%, est. MF vacancy ~2.0%; 1-mile avg HH income $210,151+; 1127 submarket units in the pipeline. No rent control disclosed.',null,'Supply-constrained, high-income submarkets protect occupancy and pricing power — the demand side of the thesis. A PASS here proves the rule set discriminates rather than flagging everything.','None — mitigant present.','Confirm the multifamily (not office/retail) vacancy and 2024–2028 delivery pipeline with CoStar.',false,false)
) as f(rule_id,rule_name,category,status,severity,level,weight,points_lost,evidence,om_page,why_it_matters,financial_impact,recommended_next_action,additional_dd_required,guardrail);